import {canonicalSha256} from '../core/canonical-json.mjs';
const SHA=/^[a-f0-9]{64}$/;
const bumpMinor=(version)=>{const [major='0',minor='0']=String(version).split('.');return`${Number(major)}.${Number(minor)+1}.0`;};
export function proposeSkillEvolution({baseSkill,cluster}={}){if(!baseSkill?.id||!SHA.test(String(baseSkill.contentSha256)))throw new TypeError('Base skill identity and digest are required');if(!cluster?.clusterSha256||cluster.instinctIds?.length<2)throw new Error('Evolution requires a repeated instinct cluster');const payload={schemaVersion:1,id:baseSkill.id,baseVersion:baseSkill.version,version:bumpMinor(baseSkill.version),maturity:'candidate',baseContentSha256:baseSkill.contentSha256,clusterId:cluster.clusterId,clusterSha256:cluster.clusterSha256,mechanism:cluster.mechanism,sourceTrustDomains:[...(cluster.trustDomains??[])].sort()};return Object.freeze({...payload,proposalSha256:canonicalSha256(payload)});}
export function promoteEvolution({proposal,evaluation,principal}={}){if(principal?.type!=='human'||!principal.roles?.includes('skill-promoter'))throw new Error('Human skill promoter is required');if(evaluation?.status!=='pass'||!Number.isFinite(evaluation.lowerBound)||evaluation.lowerBound<=0||!SHA.test(String(evaluation.receiptSha256)))throw new Error('Positive trusted evaluation receipt is required');if(!evaluation.evaluator?.roles?.includes('skill-evaluator'))throw new Error('Independent skill evaluator is required');const domains=new Set([...(proposal.sourceTrustDomains??[]),principal.trustDomain]);if(domains.has(evaluation.evaluator.trustDomain)||proposal.sourceTrustDomains?.includes(principal.trustDomain))throw new Error('Independent trust domains are required for evaluation and promotion');const payload={schemaVersion:1,id:proposal.id,version:proposal.version,baseVersion:proposal.baseVersion,maturity:'stable',proposalSha256:proposal.proposalSha256,evaluationReceiptSha256:evaluation.receiptSha256,evaluatedBy:evaluation.evaluator.id,promotedBy:principal.id,promotedAt:new Date().toISOString()};return Object.freeze({...payload,promotionSha256:canonicalSha256(payload)});}
export function rollbackEvolution({promotion,reason,principal}={}){if(principal?.type!=='human'||!principal.roles?.includes('skill-promoter'))throw new Error('Human skill promoter is required');if(!reason?.trim())throw new TypeError('Rollback reason is required');const payload={schemaVersion:1,status:'rolled-back',skillId:promotion.id,removedVersion:promotion.version,restoredVersion:promotion.baseVersion,promotionSha256:promotion.promotionSha256,reason:reason.trim(),rolledBackBy:principal.id,rolledBackAt:new Date().toISOString()};return Object.freeze({...payload,rollbackSha256:canonicalSha256(payload)});}
